cd /tmp && python3 -I -c '
import csv, io
for s in ["a,b\n\"x,y\n", "a,b\nx\0y,z\n", "a,b\n\"q\nr\",s\n\n,\n  , \nt,u\n"]:
    r = csv.reader(io.StringIO(s))
    try:
        while True:
            start = r.line_num + 1
            row = next(r)
            print(repr(row), "start", start, "end", r.line_num)
    except StopIteration: print("--end")
    except csv.Error as e: print("csv.Error", e)
'

